// [S1] 訊息類型檢查、[B2] 長度限制、[B3] Rate Limiting
const body = $input.item.json.body || $input.item.json;
const message = body.message || '';
const sessionId = body.sessionId || 'unknown';

// S1: 驗證 message 為非空字串
if (!message || typeof message !== 'string') {
  return [{ json: { ...body, isValid: false, errorMessage: '請輸入您的問題，謝謝！' } }];
}

// B2: 訊息長度上限 500 字
if (message.length > 500) {
  return [{ json: { ...body, isValid: false, errorMessage: '訊息過長（超過500字），請簡短描述問題，謝謝。' } }];
}

// B3: Rate Limiting（每分鐘最多 10 則）
const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};

const now = Date.now();
const windowMs = 60 * 1000;
const maxRequests = 10;

const userLimits = staticData.rateLimits[sessionId] || { count: 0, windowStart: now };
if (now - userLimits.windowStart > windowMs) {
  userLimits.count = 0;
  userLimits.windowStart = now;
}
userLimits.count++;
staticData.rateLimits[sessionId] = userLimits;

// 定期清理過期資料
const entries = Object.entries(staticData.rateLimits);
if (entries.length > 500) {
  staticData.rateLimits = Object.fromEntries(
    entries.filter(([, v]) => now - v.windowStart < windowMs * 10)
  );
}

if (userLimits.count > maxRequests) {
  return [{ json: { ...body, isValid: false, errorMessage: '您的訊息頻率過高，請稍後 1 分鐘再試。' } }];
}

return [{ json: { ...body, isValid: true, errorMessage: null } }];

// [B2] Prompt Injection 防護 + [B6] 錯誤處理
const output = $input.item.json.output || '';
const webhookBody = $('Chat Webhook').item.json.body || $('Chat Webhook').item.json;
const rawInput = webhookBody.message || '';

// B2: 偵測用戶輸入中的 LEAD_DATA 注入嘗試
if (rawInput.toUpperCase().includes('LEAD_DATA:')) {
  return [{ json: {
    output: '很抱歉，您的訊息包含無效內容，請重新描述您的需求。',
    leadData: null,
    hasLead: false
  }}];
}

const markerIndex = output.indexOf('LEAD_DATA:');
let leadData = null;
let cleanMessage = output;

if (markerIndex !== -1) {
  const jsonStart = markerIndex + 'LEAD_DATA:'.length;
  const jsonEnd = output.indexOf('\n', jsonStart);
  const jsonStr = jsonEnd === -1 ? output.slice(jsonStart) : output.slice(jsonStart, jsonEnd);
  try {
    leadData = JSON.parse(jsonStr.trim());
    const before = output.slice(0, markerIndex).trim();
    const after = jsonEnd !== -1 ? output.slice(jsonEnd + 1).trim() : '';
    cleanMessage = (before + '\n' + after).trim();
  } catch(e) {
    cleanMessage = '系統處理發生問題，請重新提供您的聯絡資料，謝謝。';
  }
}

// B6: 確保回覆內容不為空
if (!cleanMessage || cleanMessage.trim() === '') {
  cleanMessage = '抱歉，系統發生問題，請稍後重試。';
}

return [{ json: { output: cleanMessage, leadData, hasLead: leadData !== null } }];
